const out = Array.from(document.querySelectorAll('a, button')).map(e => ({
  tag: e.tagName,
  txt: (e.textContent||'').trim().slice(0,60),
  visible: e.offsetParent !== null,
})).filter(c => c.visible && c.txt && /Frank/i.test(c.txt));
return JSON.stringify(out);

const els = Array.from(document.querySelectorAll('a')).filter(e => {
  const t = (e.textContent||'').trim();
  return t === 'Frank' || /^Frank(?:NEW|!)?$/.test(t);
});
if (els[0]) { els[0].click(); return 'clicked: ' + els[0].textContent.trim(); }
return 'no match';

